import { useCallback, useMemo, useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultDate?: Date;
  onChange?: (date: Date) => void;
};

const startOfDay = (date: Date): Date =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const addDays = (date: Date, amount: number): Date => {
  const next = startOfDay(date);
  next.setDate(next.getDate() + amount);
  return next;
};

const isSameDay = (a: Date | null, b: Date | null): boolean =>
  a != null && b != null && startOfDay(a).getTime() === startOfDay(b).getTime();

export default function ReportDatePicker({ defaultDate, onChange }: ReportDatePickerProps) {
  const [value, setValue] = useState<Date>(() => startOfDay(defaultDate ?? new Date()));

  const presets = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: addDays(today, -1) },
      { id: 'week-ago', label: 'Неделя назад', date: addDays(today, -7) },
    ];
  }, []);

  const select = useCallback(
    (next: Date) => {
      const normalized = startOfDay(next);
      setValue(normalized);
      onChange?.(normalized);
    },
    [onChange],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
        padding: 'var(--jx-space-4)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {presets.map((preset) => {
          const active = isSameDay(value, preset.date);
          return (
            <JxButton
              key={preset.id}
              type="button"
              size="sm"
              variant={active ? 'primary' : 'secondary'}
              aria-pressed={active}
              onClick={() => select(preset.date)}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>

      <JxCalendar
        aria-label="Дата отчёта"
        value={value}
        onValueChange={(next: Date | null) => {
          if (next) {
            select(next);
          }
        }}
      />
    </div>
  );
}

